mapper.select:
        /**洞察引擎原始数据两阶段查询第一阶段：仅查id+data_create_time**/
        select id, data_create_time from voc_anal_flow_mate_data_v
--         select id, data_create_time from voc_anal_flow_mate_data_full_v
        where

        order by data_create_time desc ,id desc
        limit #{pageNum}, #{pageSize}

/**洞察引擎原始数据两阶段查询第二阶段：根据id+data_create_time集合查询所需字段**/ select id, create_time, content_type, data_create_time, data_id, channel_code, brand, series, model, is_outer, one_id, id_car_no, mobile, email, global_id, user_id, user_name, vhl_id, vhl_vin, dlr_id, dlr_code, dlr_type, market_id, title, content, is_wsater_army, weight, is_manager_focused as isManagerFocused, is_big_v as isBigV, author_id as authorId, author_nick as authorNick, is_main_post as isMainPost, url as url, view_count as viewCount, comment_count as commentCount, like_count as likeCount, share_count as shareCount, favorite_count as favoriteCount, order_id as orderId, quest_id as questId, quest_type as questType, quest_answer_score as questAnswerScore, quest_business_type as questBusinessType, quest_business_scenario as questBusinessScenario, work_id, done, model_type, ds, data_status from voc_anal_flow_mate_data_v where id IN
#{item}
AND data_create_time >= #{startTime}
AND data_create_time <= #{endTime}
order by data_create_time desc ,id desc

/**洞察引擎获取原始数据列表0305优化**/ select f1.id, create_time, content_type, data_create_time, data_id, channel_code, brand, series, model, is_outer, one_id, id_car_no, mobile, email, global_id, user_id, user_name, vhl_id, vhl_vin, dlr_id, dlr_code, dlr_type, market_id, title, content, is_wsater_army, weight, is_manager_focused as isManagerFocused, is_big_v as isBigV, author_id as authorId, author_nick as authorNick, is_main_post as isMainPost, url as url, view_count as viewCount, comment_count as commentCount, like_count as likeCount, share_count as shareCount, favorite_count as favoriteCount, order_id as orderId, quest_id as questId, quest_type as questType, quest_answer_score as questAnswerScore, quest_business_type as questBusinessType, quest_business_scenario as questBusinessScenario, work_id, done, model_type, ds, data_status from (select id from voc_anal_flow_mate_data_v where
order by data_create_time desc,id desc limit #{pageNum},#{pageSize} ) f1 left join voc_anal_flow_mate_data_v f2 on f1.id = f2.id where
order by f2.data_create_time desc,f1.id desc

